      SUBROUTINE SPREADCC     EXPAND DATA STORAGE TO HOLD COORDINATE TRANSFORMATIONS FROMC     MISALIGNMENTSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM24D.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'ICOPY.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDCARD.CIN'C      EXTERNAL        IDATAC      IIOLD = 0      CALL EXILEC      ISTOR(1) = 1      NUM = NELLIM - NEL + 1      NDIF = 1      NEL = 0      I = 1      I100 = 0      IB100 = ISTOR(NUM)      CALL FND100C      IF (NUM .GE. NELLIM + 1) GO TO 5300   50 II = ISTOR(NUM)      TYPE = IABS(IDATA(II))      LABLE = LABEL(NUM)      NPARMS = 0      IF (NUSE .EQ. 0 .AND. II .LT. IIOLD) GO TO 5000      CALL SKETCH(NUM)      NPOLD = NPARMS      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5000      IF (TYPE .EQ. 3) GO TO 300      IF (TYPE .EQ. 5) GO TO 500      IF (TYPE .EQ. 6) GO TO 600      IF (TYPE .EQ. 8) GO TO 800      IF (TYPE .EQ. 18) GO TO 1800      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPE .EQ. 30) GO TO 3000      IF (TYPE .EQ. 35 .OR. TYPE .EQ. 36) GO TO 3500      IF (TYPE .EQ. 37) GO TO 3700      GO TO 5000CC     3. -- DRIFTC  300 NPSAVE = NPARMS      CALL FIX23L      CALL FIX23H      NPARMS = NPSAVE      NPOLD = NPARMS      GO TO 5000CC     5. -- QUADC  500 GO TO 4500CC     6. -- UPDATEC  600 NSLIT = INT(DATA(II+1))      IF (NSLIT .EQ. 0) THEN        IUP = INT(DATA(II+2))        IF (IUP .EQ. 1 .OR. IUP .EQ. 2) THEN            IADR = II + IPTOJ(4)            NPARMS = NPARMS + IDATA(IADR)        ENDIF      ENDIF      GO TO 5000CC     8. -- MISALIGNMENTC  800 NPARMS = 21      GO TO 5000CC     18. -- SEXTUPOLEC 1800 GO TO 4500CC     24. -- DEFINED SECTIONC 2400 IF (NUM .EQ. NUSE) THEN        NUSE = NEL + 1      ENDIF      JDEF = IDATA(II+1)      IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) NPARMS = 1      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) NPARMS = 3      GO TO 5000CC     28. -- RBEND OR 29. -- SBENDC 2800 GO TO 4500CC     30. -- PARAMETERSC 3000 NPARMT = NPARMS      CALL FIX23L      CALL FIX23H      NPARMS = NPARMT      IF (TIE(II+1) .EQ. 99) NPARMS = NPVAR + 1      GO TO 5000CC     35. -- HKICK OR 36. -- VKICKC 3500 GO TO 4500CC     37. -- ALIGNMENT MARKERC 3700 NSLIT = INT(DATA(II+1))      IF (NSLIT .EQ. 0) THEN        IUP = INT(DATA(II+2))        IF (IUP .EQ. 1 .OR. IUP .EQ. 2) THEN            IADR = II + IPTOJ(4)            NPARMS = NPARMS + IDATA(IADR)        ENDIF      ENDIF      GO TO 5000CC     REVISE REFERENCES ON MISALIGNMENTSC 4500 CALL FIX8H      GO TO 5000CC     CHANGE REFERENCES TO PHYSICAL PARAMETERSC 5000 NEL = NEL + 1      IF (NUSE .EQ. 0 .AND. II .LT. IIOLD) GO TO 5100      NP1 = NPOLD + 1      IIPN = II + NPARMS      IF (I100 .EQ. 0 .OR. I100 .GT. IIPN) GO TO 5020      DO 5010 J = 1, NP1      IADR = II + J      IF (IADR .EQ. I100) THEN        IANEW = ISTOR(NEL) + J        CALL FIXREF        CALL FND100        IF (I100 .GT. IIPN) GO TO 5020      ENDIF 5010 CONTINUECC     COPY ELEMENT TO LIST AT BEGINNING OF DATA ARRAYC 5020 DO 5030 J = 1, NP1      I1 = II + J - 1      DATA(I) = DATA(I1)      TIE(I) = TIE(I1)      I = I + 1 5030 CONTINUE      ICOPY = I1      IF (NPARMS .GT. NPOLD) THEN        NP2 = NP1 + 1        NP1 = NPARMS + 1        DO 5040 J = NP2, NP1        DATA(I) = 0.0        TIE(I) = 0        I = I + 1 5040   CONTINUE      ENDIF      IF (.NOT. FLUSHL) ISTOR(NEL+1) = I      IIOLD = MAX0(II,IIOLD)      GO TO 5180C 5100 IF (NEL .EQ. 0) GO TO 5180      DO 5120 NN = 1, NEL      NNN = NN      IF (LABEL(NN) .EQ. LABLE) GO TO 5150 5120 CONTINUE 5150 ISTOR(NEL) = ISTOR(NNN)      IF (.NOT. FLUSHL) ISTOR(NEL+1) = IC 5180 NDESCR(NEL) = NDESCR(NUM)      LABEL(NEL) = LABLEC 5200 NUM = NUM + 1      IF (NUM .LE. NELLIM) GO TO 50C 5300 RETURN      END